  status
  creation_time
  last_update_time
  channel_name
  channel_jid
  appeal_reason_options {
    reason
    label
    server_msg_id
    server_id
    server_response_id
    notify_name
    appeal {
      state
      appeal_reason
      appeal_id
      __typename
      xwa2_create_channel_report_appeal_v2 {
        reported_content_data {
          question_data {
            xwa2_create_channel_report_appeal_v2 {
              reported_content_data {
                question_data {
                }
              }
            }
          }
        }
      }
    }
  }
}
